    ["For bar backgrounds: Bar Background Tint. White in Dark Mode needs Custom color in Dark Mode; black track? check Preserve HP color."] = "For bar backgrounds: Bar Background Tint. White in Dark Mode needs Custom color in Dark Mode; black track? check Preserve HP color.",
