    ["Link"] = "Link",
    ["MSUF Dispel Border / Glow"] = "MSUF Dispel Border / Glow",
    ["MSUF Edit Mode moves frames and supported castbars. Aura icon placement is controlled from Unit Auras or Group Frames > Buffs & Debuffs."] = "MSUF Edit Mode moves frames and supported castbars. Aura icon placement is controlled from Unit Auras or Group Frames > Buffs & Debuffs.",
    ["MSUF Focus"] = "MSUF Focus",
    ["MSUF Smooth v2"] = "MSUF Smooth v2",
    ["MSUF group frames do not use per-player castbars over the health frame. For MSUF castbar positioning, use MSUF Edit Mode and Global Style > Castbar."] = "MSUF group frames do not use per-player castbars over the health frame. For MSUF castbar positioning, use MSUF Edit Mode and Global Style > Castbar.",
