    ["Menu %d%%"] = "Menu %d%%",
    ["Mode"] = "Mode",
    ["Modules"] = "Modules",
    ["Most shared colors are in Global Style > Colors. Bar texture and border style controls are in Global Style > Bars."] = "Most shared colors are in Global Style > Colors. Bar texture and border style controls are in Global Style > Bars.",
    ["Name"] = "Name",
    ["New character profile"] = "New character profile",
    ["Not Now"] = "Not Now",
    ["Okay"] = "Okay",
    ["One-click setup for a ready-to-use class bar:"] = "One-click setup for a ready-to-use class bar:",
    ["Open Class Resources for combo points, holy power, soul shards, chi, maelstrom, essence, runes, stagger, detached power, and alternative mana."] = "Open Class Resources for combo points, holy power, soul shards, chi, maelstrom, essence, runes, stagger, detached power, and alternative mana.",
    ["Open Class Resources for global class-resource bars. Per-unit detached power options are in the unit page > Power Bar."] = "Open Class Resources for global class-resource bars. Per-unit detached power options are in the unit page > Power Bar.",
    ["Open Class Resources. Check Enable, Auto-Hide, class-specific behavior, detached power, and alternative mana settings."] = "Open Class Resources. Check Enable, Auto-Hide, class-specific behavior, detached power, and alternative mana settings.",
    ["Open Focus Target. Use Frame Basics to enable it; it only appears when Focus is enabled and your focus has a target."] = "Open Focus Target. Use Frame Basics to enable it; it only appears when Focus is enabled and your focus has a target.",
    ["Open Gameplay for crosshair, click-cast, focus/target modifier, mouseover, interaction, and targeting options."] = "Open Gameplay for crosshair, click-cast, focus/target modifier, mouseover, interaction, and targeting options.",
    ["Open Global Style > Bars. Textures & Gradient controls shared bar textures; Frame Outline and Highlight Borders control borders."] = "Open Global Style > Bars. Textures & Gradient controls shared bar textures; Frame Outline and Highlight Borders control borders.",
    ["Open Global Style > Castbar > GCD Bar. It controls instant-cast GCD display, time text, spell name, and icon."] = "Open Global Style > Castbar > GCD Bar. It controls instant-cast GCD display, time text, spell name, and icon.",
    ["Open Global Style > Castbar > Name Shortening for castbar spell name shortening, max length, and reserved space."] = "Open Global Style > Castbar > Name Shortening for castbar spell name shortening, max length, and reserved space.",
    ["Open Global Style > Castbar and use Empowered Casts for Evoker stage color, stage blink, and blink timing."] = "Open Global Style > Castbar and use Empowered Casts for Evoker stage color, stage blink, and blink timing.",
    ["Open Global Style > Castbar for Focus Kick and Interrupt Ready Indicator. Per-unit castbar interrupt toggles are on each unit page."] = "Open Global Style > Castbar for Focus Kick and Interrupt Ready Indicator. Per-unit castbar interrupt toggles are on each unit page.",
    ["Open Global Style > Colors for class bar colors and unitframe colors. Group health colors are in Group Frames > Health & Text."] = "Open Global Style > Colors for class bar colors and unitframe colors. Group health colors are in Group Frames > Health & Text.",
    ["Open Global Style > Colors. Bar Colors and Power Bar Colors control HP/power colors; Class Bar Colors controls class overrides."] = "Open Global Style > Colors. Bar Colors and Power Bar Colors control HP/power colors; Class Bar Colors controls class overrides.",
    ["Open Global Style > Fonts > Name Shortening for unit names. Castbar spell name shortening is in Global Style > Castbar > Name Shortening."] = "Open Global Style > Fonts > Name Shortening for unit names. Castbar spell name shortening is in Global Style > Castbar > Name Shortening.",
    ["Open Global Style > Fonts > Name Shortening. It controls name shortening globally; unit text placement is on each unit page > Text."] = "Open Global Style > Fonts > Name Shortening. It controls name shortening globally; unit text placement is on each unit page > Text.",
    ["Open Global Style > Miscellaneous > Blizzard Frames and use Play sound on Target/Target Lost."] = "Open Global Style > Miscellaneous > Blizzard Frames and use Play sound on Target/Target Lost.",
    ["Open Global Style > Miscellaneous > Blizzard Frames and use Show MSUF minimap icon."] = "Open Global Style > Miscellaneous > Blizzard Frames and use Show MSUF minimap icon.",
    ["Open Global Style > Miscellaneous > Language. Translation coverage can also be checked with the /msuf locale command."] = "Open Global Style > Miscellaneous > Language. Translation coverage can also be checked with the /msuf locale command.",
    ["Open Global Style > Miscellaneous > Menu behavior for edge snap and related menu behavior."] = "Open Global Style > Miscellaneous > Menu behavior for edge snap and related menu behavior.",
    ["Open Global Style > Miscellaneous > Range Fade. It controls target, focus, and boss out-of-range fading; group range fade is in Group Frames > Health & Text."] = "Open Global Style > Miscellaneous > Range Fade. It controls target, focus, and boss out-of-range fading; group range fade is in Group Frames > Health & Text.",
    ["Open Global Style > Miscellaneous > Unitframe tooltips to control mouseover tooltip behavior."] = "Open Global Style > Miscellaneous > Unitframe tooltips to control mouseover tooltip behavior.",
    ["Open the unit page > Frame Basics and use Force Blizzard frame on."] = "Open the unit page > Frame Basics and use Force Blizzard frame on.",
    ["Open Global Style > Miscellaneous and use the Range Fade section for affected units, alpha, and portrait fading."] = "Open Global Style > Miscellaneous and use the Range Fade section for affected units, alpha, and portrait fading.",
    ["Open Group Frames > Buffs & Debuffs for raid/party aura handling and Aura Utilities. Unit-frame aura filters are in Unit Auras."] = "Open Group Frames > Buffs & Debuffs for raid/party aura handling and Aura Utilities. Unit-frame aura filters are in Unit Auras.",
    ["Open Group Frames > Buffs & Debuffs. Use Buffs, custom buffs, and aura filters to prioritize your own HoTs, externals, and healer buffs."] = "Open Group Frames > Buffs & Debuffs. Use Buffs, custom buffs, and aura filters to prioritize your own HoTs, externals, and healer buffs.",
    ["Open Group Frames > Health & Text > Range Fade. That controls party and raid out-of-range fading."] = "Open Group Frames > Health & Text > Range Fade. That controls party and raid out-of-range fading.",
    ["Open Group Frames > Health & Text. It controls health colors, bars, power bar, text, heal prediction, dispel overlay, debuff stripe, and range fade."] = "Open Group Frames > Health & Text. It controls health colors, bars, power bar, text, heal prediction, dispel overlay, debuff stripe, and range fade.",
    ["Open Group Frames > Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators."] = "Open Group Frames > Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators.",
    ["Open Group Frames > Layout and check the solo/player visibility options. That is where MSUF controls whether party-style frames appear when you are alone."] = "Open Group Frames > Layout and check the solo/player visibility options. That is where MSUF controls whether party-style frames appear when you are alone.",
    ["Open Group Frames > Layout for Smooth health fill. For group-frame power bars, open Group Frames > Health & Text > Power Bar > Smooth fill."] = "Open Group Frames > Layout for Smooth health fill. For group-frame power bars, open Group Frames > Health & Text > Power Bar > Smooth fill.",
    ["Open Group Frames > Layout. Check enable/show behavior, player/solo visibility, layout mode, frame scaling, and anchoring."] = "Open Group Frames > Layout. Check enable/show behavior, player/solo visibility, layout mode, frame scaling, and anchoring.",
    ["Open Group Frames > Layout. General/Layout controls frame width, height, spacing, columns, and growth; Frame Scaling controls scale behavior."] = "Open Group Frames > Layout. General/Layout controls frame width, height, spacing, columns, and growth; Frame Scaling controls scale behavior.",
    ["Open Group Frames > Layout. The General and Sorting sections control player/self visibility and how player units are ordered in group frames."] = "Open Group Frames > Layout. The General and Sorting sections control player/self visibility and how player units are ordered in group frames.",
    ["Open Group Frames > Layout. Use Layout, Frame Scaling, and Anchoring for party/raid position, growth, spacing, size, and anchor behavior."] = "Open Group Frames > Layout. Use Layout, Frame Scaling, and Anchoring for party/raid position, growth, spacing, size, and anchor behavior.",
    ["Open MSUF Edit Mode, select the frame, then drag it. Use the unit page > Anchoring only for exact anchor/X/Y fine-tuning."] = "Open MSUF Edit Mode, select the frame, then drag it. Use the unit page > Anchoring only for exact anchor/X/Y fine-tuning.",
    ["Open MSUF again with /msuf. If frame positions are broken, use Dashboard > Reset Positions or the profile/reset tools."] = "Open MSUF again with /msuf. If frame positions are broken, use Dashboard > Reset Positions or the profile/reset tools.",
    ["Open Modules > Style for optional style modules such as portrait decoration and dropdown styling."] = "Open Modules > Style for optional style modules such as portrait decoration and dropdown styling.",
    ["Open Profiles for active profile, spec auto-switching, import/export strings, legacy imports, and reset options."] = "Open Profiles for active profile, spec auto-switching, import/export strings, legacy imports, and reset options.",
    ["Open Profiles. Check active profile, spec profiles, import/export, and legacy imports. Large imports may need a reload."] = "Open Profiles. Check active profile, spec profiles, import/export, and legacy imports. Large imports may need a reload.",
    ["Open Target of Target. Use Frame Basics to enable it, Text for labels, and Anchoring/Edit Mode for placement."] = "Open Target of Target. Use Frame Basics to enable it, Text for labels, and Anchoring/Edit Mode for placement.",
    ["Open Unit Auras > Caps & Icons. Lower max buffs/debuffs, rows, icon size, and adjust filters."] = "Open Unit Auras > Caps & Icons. Lower max buffs/debuffs, rows, icon size, and adjust filters.",
    ["Open Unit Auras > Text Coloring for timer colors and text sizes. Group aura cooldown style is in Group Frames > Buffs & Debuffs > Cooldown Style."] = "Open Unit Auras > Text Coloring for timer colors and text sizes. Group aura cooldown style is in Group Frames > Buffs & Debuffs > Cooldown Style.",
    ["Open Unit Auras and use Display plus Caps & Icons for unit-frame aura placement. Buff/debuff icons are configured as aura layout, not moved through MSUF Edit Mode."] = "Open Unit Auras and use Display plus Caps & Icons for unit-frame aura placement. Buff/debuff icons are configured as aura layout, not moved through MSUF Edit Mode.",
    ["Open Unit Auras for unit-frame aura icon sizing and filters. For group frames, use Group Frames > Buffs & Debuffs and custom buff/debuff controls."] = "Open Unit Auras for unit-frame aura icon sizing and filters. For group frames, use Group Frames > Buffs & Debuffs and custom buff/debuff controls.",
    ["Open Unit Auras for unit-frame debuff filtering. For party/raid dispels, use Group Frames > Indicators and Group Frames > Buffs & Debuffs."] = "Open Unit Auras for unit-frame debuff filtering. For party/raid dispels, use Group Frames > Indicators and Group Frames > Buffs & Debuffs.",
    ["Open Unit Auras, select Player, enable Custom caps, then set Caps & Icons > Max Buffs to 0. Show Buffs is a shared master toggle, so it is locked outside Shared."] = "Open Unit Auras, select Player, enable Custom caps, then set Caps & Icons > Max Buffs to 0. Show Buffs is a shared master toggle, so it is locked outside Shared.",
    ["Open Unit Auras. Check Display, Aura Filters & Sorting, Only Mine, boss aura filters, dispellable filters, and icon caps."] = "Open Unit Auras. Check Display, Aura Filters & Sorting, Only Mine, boss aura filters, dispellable filters, and icon caps.",
    ["Open that unit page and use Frame Basics > Enable. Boss frames also have Boss Layout options."] = "Open that unit page and use Frame Basics > Enable. Boss frames also have Boss Layout options.",
    ["Open that unit page and use Frame Basics for width, height, and scale. Text size is in Global Style > Fonts or the unit Text section."] = "Open that unit page and use Frame Basics for width, height, and scale. Text size is in Global Style > Fonts or the unit Text section.",
    ["Open the matching unit page and check Frame Basics > Enable, Load Conditions, alpha/transparency, and range fade."] = "Open the matching unit page and check Frame Basics > Enable, Load Conditions, alpha/transparency, and range fade.",
    ["Open the matching unit page and use Load Conditions to control when player, target, focus, boss, or pet frames are shown."] = "Open the matching unit page and use Load Conditions to control when player, target, focus, boss, or pet frames are shown.",
    ["Open the unit page > Castbar to enable that unit's castbar. Shared castbar visuals are in Global Style > Castbar."] = "Open the unit page > Castbar to enable that unit's castbar. Shared castbar visuals are in Global Style > Castbar.",
    ["Open the unit page > Status icons. Select Level in Indicator, then use Enabled, Anchor, X/Y Offset, Size, and Layer."] = "Open the unit page > Status icons. Select Level in Indicator, then use Enabled, Anchor, X/Y Offset, Size, and Layer.",
    ["Open the unit page > Text. Adjust anchors, offsets, font size, spacing, split spacing, and layer."] = "Open the unit page > Text. Adjust anchors, offsets, font size, spacing, split spacing, and layer.",
    ["Open the unit page > Transparency for in-combat/out-of-combat alpha. By default the sliders fade the whole frame; Keep text + portrait visible switches them to the selected layer: Bars, HP Bar, or Backdrop. Group frame transparency is in Group Frames > Layout > Transparency."] = "Open the unit page > Transparency for in-combat/out-of-combat alpha. By default the sliders fade the whole frame; Keep text + portrait visible switches them to the selected layer: Bars, HP Bar, or Backdrop. Group frame transparency is in Group Frames > Layout > Transparency.",
    ["Open the unit page and use Text for name/health/power text patterns, anchors, offsets, font sizes, and layering."] = "Open the unit page and use Text for name/health/power text patterns, anchors, offsets, font sizes, and layering.",
    ["Open the unit page, then use Frame Basics > Smooth fill for the health bar. For that unit's power bar animation, open Power Bar > Smooth fill."] = "Open the unit page, then use Frame Basics > Smooth fill for the health bar. For that unit's power bar animation, open Power Bar > Smooth fill.",
    ["Open the unit page, then use the Portrait section for mode, render type, shape, size, offset, and border."] = "Open the unit page, then use the Portrait section for mode, render type, shape, size, offset, and border.",
