L["Yes. Include tanks automatically selects current group members whose WoW-assigned role is TANK, normally including both you and your co-tank. To show only your co-tank, disable automatic tanks and manually pin the other tank. If WoW has not assigned that player the TANK role, manual pinning is the fallback."] = "Yes. Include tanks automatically selects current group members whose WoW-assigned role is TANK, normally including both you and your co-tank. To show only your co-tank, disable automatic tanks and manually pin the other tank. If WoW has not assigned that player the TANK role, manual pinning is the fallback."
L["Yes. Priority Frames inherit the active Party, Raid, or Mythic Raid frame appearance, including configured bars, text, auras, status indicators, and spell indicators. They use the same MSUF click-casting registration and unit behavior, so existing click-cast bindings also work on the duplicated frames."] = "Yes. Priority Frames inherit the active Party, Raid, or Mythic Raid frame appearance, including configured bars, text, auras, status indicators, and spell indicators. They use the same MSUF click-casting registration and unit behavior, so existing click-cast bindings also work on the duplicated frames."
L["Yes. Priority Frames work in parties, raids, and Mythic raids. In a party or dungeon they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid setup. They do not create a solo strip, and the matching base Party or Raid frames must be enabled."] = "Yes. Priority Frames work in parties, raids, and Mythic raids. In a party or dungeon they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid setup. They do not create a solo strip, and the matching base Party or Raid frames must be enabled."
